function status(message,type='ok'){
 let x=document.getElementById('statusbar');if(!x){x=document.createElement('div');x.id='statusbar';x.className='statusbar';document.body.appendChild(x)}
 x.textContent=message;x.className='statusbar '+type;clearTimeout(status.timer);status.timer=setTimeout(()=>x.remove(),2600);
}
function enhanceSelects(){
 document.querySelectorAll('#app select').forEach((sel,i)=>{
  if(sel.dataset.searchReady==='1'||sel.options.length<8)return;sel.dataset.searchReady='1';
  const input=document.createElement('input');input.type='search';input.className='select-search no-print';input.placeholder='ค้นหาใน Dropdown...';
  const all=[...sel.options].map(o=>({value:o.value,text:o.text,selected:o.selected}));
  input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase(),value=sel.value;sel.innerHTML='';all.filter(o=>!q||o.text.toLowerCase().includes(q)||String(o.value).toLowerCase().includes(q)).forEach(o=>sel.add(new Option(o.text,o.value,false,o.value===value)));if(!sel.options.length)sel.add(new Option('ไม่พบข้อมูล',''));});
  sel.parentNode.insertBefore(input,sel);
 });
}
function printSettings(){
 const matrixPrint=current==='matrix'; const cardPrint=current==='cards';
 modal(`<h2>ตั้งค่าการพิมพ์ / Save as PDF</h2><div class="print-settings"><label>ขนาดกระดาษ<select id="paperSize"><option ${matrixPrint?'':'selected'}>A4</option><option ${matrixPrint?'selected':''}>A3</option></select></label><label>แนวกระดาษ<select id="paperOrientation"><option value="portrait" ${matrixPrint?'':'selected'}>แนวตั้ง</option><option value="landscape" ${matrixPrint?'selected':''}>แนวนอน</option></select></label><label>ขนาดเนื้อหา<select id="paperScale"><option>70</option><option>80</option><option>90</option><option ${matrixPrint?'selected':''}>100</option><option>110</option><option>120</option></select></label></div><p>${matrixPrint?'แนะนำ: A3 แนวนอน 100% รูปแบบเดียวกับไฟล์ PDF และรูปพนักงานชัดขึ้น':'หลังจากกดพิมพ์ สามารถเลือกเครื่องพิมพ์ หรือ Save as PDF ได้'}</p><div class="actions"><button id="doPrint">พิมพ์ตอนนี้</button><button class="secondary" data-action="close">ยกเลิก</button></div>`);
 const btn=document.getElementById('doPrint');if(btn)btn.onclick=()=>{const size=document.getElementById('paperSize').value,orientation=document.getElementById('paperOrientation').value,scale=document.getElementById('paperScale').value;let st=document.getElementById('dynamicPrintStyle');if(!st){st=document.createElement('style');st.id='dynamicPrintStyle';document.head.appendChild(st)}st.textContent=matrixPrint?`@page{size:${size} ${orientation};margin:6mm}`:`@page{size:${size} ${orientation};margin:8mm}`;document.body.className=document.body.className.replace(/print-scale-\d+|print-matrix/g,'').trim()+` print-scale-${scale}${matrixPrint?' print-matrix':''}`;closeModal();setTimeout(()=>window.print(),100)};
}
function employeeExportRows(list=employees){return list.map(e=>({ID:e.id,Name:e.name,ThaiName:e.thaiName||'',Phone:e.phone||'',Section:e.section,Position:e.position,StartDate:e.startDate||'',Contract:e.contractType||'',Team:e.shift||''}))}
function skillExportRows(list=employees){return list.map(e=>{const skills=skillsFor(e.section),row={ID:e.id,Name:e.name,Section:e.section,Position:e.position};skills.forEach(k=>row[k]=skillValue(e,k));row.Score=skillScore(e,skills);row.Acceptance=acceptance(row.Score,skills.length).label;return row})}
function excelSafe(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}

async function matrixPdfDownload(){
 const report=document.querySelector('.matrix-report');
 if(!report)return alert('ไม่พบข้อมูล Skill Matrix');
 if(typeof html2canvas==='undefined'||!window.jspdf){return alert('ไม่สามารถโหลดระบบสร้าง PDF ได้ กรุณาเชื่อมต่ออินเทอร์เน็ตแล้วลองใหม่');}
 const selected=sessionStorage.getItem('matrixSec')||sections[0];
 status('กำลังสร้างไฟล์ PDF...');
 try{
  const canvas=await html2canvas(report,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false,ignoreElements:el=>el.classList&&el.classList.contains('no-print')});
  const {jsPDF}=window.jspdf;
  const pdf=new jsPDF({orientation:'landscape',unit:'mm',format:'a3',compress:true});
  const pageW=pdf.internal.pageSize.getWidth(),pageH=pdf.internal.pageSize.getHeight();
  const margin=6,usableW=pageW-margin*2,usableH=pageH-margin*2;
  const imgW=usableW,imgH=canvas.height*imgW/canvas.width;
  const pageCanvas=document.createElement('canvas');
  const pxPerMm=canvas.width/imgW;
  const slicePx=Math.floor(usableH*pxPerMm);
  let y=0,page=0;
  while(y<canvas.height){
   const h=Math.min(slicePx,canvas.height-y);
   pageCanvas.width=canvas.width;pageCanvas.height=h;
   const ctx=pageCanvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,pageCanvas.width,pageCanvas.height);ctx.drawImage(canvas,0,y,canvas.width,h,0,0,canvas.width,h);
   const sliceH=h/pxPerMm;
   if(page>0)pdf.addPage('a3','landscape');
   pdf.addImage(pageCanvas.toDataURL('image/jpeg',0.92),'JPEG',margin,margin,imgW,sliceH,undefined,'FAST');
   y+=h;page++;
  }
  const safe=selected.replace(/[^A-Za-z0-9ก-๙_-]+/g,'_');
  pdf.save(`Skill_Matrix_${safe}.pdf`);
  status('ดาวน์โหลด PDF แล้ว','ok');
 }catch(err){console.error(err);alert('สร้าง PDF ไม่สำเร็จ: '+err.message);status('สร้าง PDF ไม่สำเร็จ','error')}
}

function matrixExcelDownload(){
 const selected=sessionStorage.getItem('matrixSec')||sections[0],skills=skillsFor(selected),list=employees.filter(e=>e.section===selected);
 const headers=['No.','Emp.ID','Name','Position',...skills,'Score','Acceptance','Last Update','Quarter','Evaluator'];
 const body=list.map((e,i)=>{const score=skillScore(e,skills),a=acceptance(score,skills.length),d=skillDates(e);return [i+1,e.id,e.name,e.position,...skills.map(k=>skillValue(e,k)),score,`Level ${a.level} - ${a.label}`,d.last,e.skillQuarter||'',e.skillEvaluator||'']});
 const title=`SECTION SKILL MATRIX - ${selected}`;
 const th=headers.map(h=>`<th>${excelSafe(h)}</th>`).join('');
 const tr=body.map(r=>`<tr>${r.map((v,i)=>`<td class="${i>=4&&i<4+skills.length+1?'num':''}">${excelSafe(v)}</td>`).join('')}</tr>`).join('');
 const criteria=[1,2,3,4,5].map(level=>{const min=(level-1)*skills.length+skills.length,max=level*skills.length;const labels=['Basic Knowledge','Basic Operation','Independent Operation','Advanced Skill','Expert / Trainer'];return `<tr><td>Level ${level}</td><td>${min}-${max}</td><td>${labels[level-1]}</td></tr>`}).join('');
 const html=`<!doctype html><html><head><meta charset="UTF-8"><style>body{font-family:Arial,'Tahoma',sans-serif}h1{background:#164d84;color:white;padding:12px}table{border-collapse:collapse;width:100%}th{background:#d9e9f7;color:#073b67;font-weight:bold;text-align:center}td,th{border:1px solid #9fb8cf;padding:6px}.num{text-align:center}.meta{margin:6px 0 14px;color:#444}.criteria{margin-top:18px}.criteria th{background:#173f68;color:#fff}</style></head><body><h1>${excelSafe(title)}</h1><div class="meta">Exported: ${excelSafe(new Date().toLocaleString('th-TH'))} | Employees: ${list.length}</div><table><thead><tr>${th}</tr></thead><tbody>${tr}</tbody></table><table class="criteria"><thead><tr><th>Level</th><th>Score</th><th>Description</th></tr></thead><tbody>${criteria}</tbody></table></body></html>`;
 dl(`Skill_Matrix_${selected.replace(/[^A-Za-z0-9ก-๙_-]+/g,'_')}.xls`,'\ufeff'+html,'application/vnd.ms-excel;charset=utf-8');status('ดาวน์โหลด Excel แล้ว');
}
